def semver_sort(versions):
    def parse_key(v):
        # Strip build metadata
        main = v.split('+', 1)[0]
        if '-' in main:
            core, prerelease = main.split('-', 1)
            has_pre = 0
        else:
            core = main
            prerelease = None
            has_pre = 1

        core_parts = core.split('.')
        major, minor, patch = (int(x) for x in core_parts[:3])

        if prerelease is not None:
            idents = prerelease.split('.')
            ident_keys = []
            for ident in idents:
                if ident.isdigit():
                    ident_keys.append((0, int(ident)))
                else:
                    ident_keys.append((1, ident))
        else:
            ident_keys = []

        return (major, minor, patch, has_pre, ident_keys, len(ident_keys))

    return sorted(versions, key=parse_key)

